import javax.microedition.lcdui.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Method;
/** Actual production Canvas rendering with desktop-only fonts; no Bluetooth. */
public final class NativeUISnapshots implements NWalletCanvas.Host {
 public void connect(){}public void lock(){}public void exit(){}public void settings(int item){}public void saveLanguage(int value){}public void submitPin(String pin){}public void allowConnection(boolean allow){}public void createSampleRoot(int words){}public void approveWallet(boolean allow){}public void cancelWallet(){}
 private static File out;private static int count;
 private static void key(NWalletCanvas c,int k)throws Exception{Method press=NWalletCanvas.class.getDeclaredMethod("keyPressed",Integer.TYPE),release=NWalletCanvas.class.getDeclaredMethod("keyReleased",Integer.TYPE);press.setAccessible(true);release.setAccessible(true);press.invoke(c,Integer.valueOf(k));release.invoke(c,Integer.valueOf(k));}
 private static void capture(NWalletCanvas c,String name)throws Exception{BufferedImage im=new BufferedImage(c.getWidth(),c.getHeight(),BufferedImage.TYPE_INT_RGB);Method paint=NWalletCanvas.class.getDeclaredMethod("paint",Graphics.class);paint.setAccessible(true);paint.invoke(c,new Graphics(im));javax.imageio.ImageIO.write(im,"png",new File(out,name+".png"));count++;}
 public static void main(String[] args)throws Exception{out=new File(args[0]);out.mkdirs();for(int language=0;language<2;language++){String suffix=language==0?"-zh":"-en";NWalletCanvas c=new NWalletCanvas(new NativeUISnapshots(),language);c.status(language==0?"未连接":"Offline",language==0?"12词样本根":"12 word root",language==0?"尚未连接":"No peer",language==0?"无":"None",false);capture(c,"home-offline"+suffix);c.status(language==0?"等待连接":"Waiting for client",language==0?"12词样本根":"12 word root",language==0?"尚未连接":"No peer",language==0?"无":"None",false);capture(c,"home-waiting"+suffix);c.status(language==0?"已授权连接":"Authorized channel",language==0?"12词样本根":"12 word root",language==0?"未知平台":"Unknown platform",language==0?"无":"None",true);capture(c,"home-connected"+suffix);
 key(c,-4);for(int i=0;i<4;i++){capture(c,"settings-"+i+suffix);if(i<3)key(c,-2);}key(c,-1);key(c,-5);capture(c,"language"+suffix);key(c,-6);key(c,-4);capture(c,"about"+suffix);key(c,-5);capture(c,"reading"+suffix);key(c,-6);
 c.chooseRoot();capture(c,"root"+suffix);key(c,-6);c.confirmWallet(language==0?"公开样本根：12词\npassphrase：\n[PUBLIC-DEMO-ONLY]\n\n长度：16\n· 表示空格，大小写与首尾空格均保留。\n确认仅打开钱包，不批准交易。":"Public fixture root: 12 words\npassphrase:\n[PUBLIC-DEMO-ONLY]\n\nLength: 16\nDots show spaces. Case and edge spaces are preserved.\nOpening does not approve a transaction.");capture(c,"passphrase"+suffix);for(int i=0;i<20;i++)key(c,-2);capture(c,"passphrase-bottom"+suffix);
 c.confirmWallet(language==0?"公开样本根：24词\npassphrase：\n（空字符串，0字符）\n\n确认仅打开钱包，不批准交易。":"Public fixture root: 24 words\npassphrase:\n(empty string, 0 characters)\n\nOpening does not approve a transaction.");capture(c,"passphrase-empty"+suffix);
 c.walletProgress(language==0?"公开样本实际派生中…\n\n可用左软键取消。\n取消后等待计算停止并清理。":"Deriving public sample addresses...\n\nUse the left softkey to cancel.\nWait for computation and cleanup to finish.");capture(c,"progress"+suffix);c.walletResult(language==0?"请求超时":"Timed out",language==0?"请求超时，请从客户端重试。\n超时不证明手机没有完成。":"Retry from the client.\nA timeout does not prove that the phone did not finish.");capture(c,"timeout"+suffix);c.invalidateConsent();c.status(language==0?"等待本次授权":"Consent required",language==0?"12词样本根":"12 word root",language==0?"未知平台":"Unknown platform",language==0?"无":"None",false);c.consent(language==0?"未知平台；核对电脑上的连接操作。":"Unknown platform. Check the connection on your computer.");capture(c,"consent"+suffix);c.invalidateConsent();c.status(language==0?"未连接":"Offline",language==0?"已锁定":"Locked",language==0?"尚未连接":"No peer",language==0?"无":"None",false);c.pin(language==0?"设置样本 PIN":"Set sample PIN",language==0?"输入4–12位数字，中键继续。仅样本应用锁，不保护真实根密钥。":"Enter 4–12 digits; press Select. Sample app lock only.");key(c,48);key(c,48);key(c,49);key(c,50);capture(c,"pin"+suffix);}
 System.out.println("PASS "+count+" production Canvas captures; desktop fonts only, no phone/radio");}
}
